/**
 * Single source of truth for the seven Renseoff products.
 *
 * Product photos: the supplied transparent PNGs live in /public/products.
 * Consistently framed WebP copies used by the site are generated by
 * `python3 scripts/normalize_product_images.py` into /public/products/optimized.
 * Replace those files and re-run the script if new photography is supplied.
 *
 * Core products are available in 500ML and 5L; air fresheners in 200ML.
 * Ingredient lists are copied from the product information supplied by Renseoff.
 *
 * Future 3D: set `model` to a path such as "/models/dishwash.glb" and the
 * ProductSection will render it through the GLB-ready React Three Fiber
 * component instead of the flat product image.
 */
export type Product = {
  id: string;
  number: string;
  name: string;
  category: string;
  tagline: string;
  description: string;
  benefits: string[];
  /** Key ingredients copied from the supplied product information. */
  ingredients?: string[];
  sizes: string[];
  fragrance: string;
  image: string;
  /** Optional size-specific photography, keyed by the size label. */
  sizeImages?: Record<string, string>;
  model?: string;
  theme: {
    bg: string;
    glow: string;
    accent: string;
    accentSoft: string;
  };
  decor: "citrus" | "botanical" | "bubbles" | "droplets" | "fresh" | "petals" | "amber";
  /** Products sharing a group are presented as one selectable item. */
  variantGroup?: string;
};

export type ProductVariant = {
  id: string;
  name: string;
  image: string;
  theme: Product["theme"];
  decor: Product["decor"];
  tagline: string;
  description: string;
  fragrance: string;
  benefits?: string[];
  ingredients?: string[];
};

export type ShowcaseProduct = Product & {
  variants?: ProductVariant[];
};

