/**
 * Products shown in the page body. The two air fresheners are grouped into one
 * selectable item here, while `products` still powers the seven-bottle hero.
 */
export const showcaseProducts: ShowcaseProduct[] = [
  ...products.filter((product) => product.variantGroup !== "air-freshener"),
  combinedAirFreshener,
  ...additionalProducts,
];

/** Resolve a selected variant into a normal product for ordering. */
export function resolveVariant(
  product: ShowcaseProduct,
  variantId?: string,
): Product {
  const variant =
    product.variants?.find((item) => item.id === variantId) ??
    product.variants?.[0];

  if (!variant) return product;

  return {
    ...product,
    id: `${product.id}-${variant.id}`,
    name: variant.name,
    image: variant.image,
    theme: variant.theme,
    decor: variant.decor,
    tagline: variant.tagline,
    description: variant.description,
    fragrance: variant.fragrance,
    benefits: variant.benefits ?? [],
    ingredients: variant.ingredients,
  };
}

/** Return the photography for the selected size, falling back to the main image. */
export function productImageForSize(product: Product, size?: string): string {
  return (size && product.sizeImages?.[size]) || product.image;
}

